namespace sv_fc51ea4e49eb4bf68592feff62d3fa39.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

export function observeScrollTop(element, dotNetRef) {
    if (!element) return;
    element.addEventListener('scroll', () => {
        if (element.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

export function scrollToBottom(element) {
    if (!element) return;
    element.scrollTop = element.scrollHeight;
}

@inherits LayoutComponentBase

<div class="chat-layout">
    @Body
</div>

.chat-layout {
    height: 100vh;
    overflow: hidden;
}

@namespace sv_fc51ea4e49eb4bf68592feff62d3fa39.Components.Chat

<div class="message-input-container">
    <textarea class="message-input-textarea" @bind="text" @bind:event="oninput"
              placeholder="@Placeholder" @onkeydown="HandleKeyDown" rows="2" />
    <button class="btn btn-primary btn-sm message-input-btn"
            @onclick="Submit" disabled="@string.IsNullOrWhiteSpace(text)">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message...";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private string text = "";

    private async Task Submit()
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        var content = text.Trim();
        text = "";
        await OnSubmit.InvokeAsync(content);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await Submit();
        }
    }
}

.message-input-container {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #dee2e6;
    background: #fff;
    align-items: flex-end;
}

.message-input-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
    outline: none;
}

.message-input-textarea:focus {
    border-color: #5865f2;
    box-shadow: 0 0 0 2px rgba(88, 101, 242, 0.2);
}

.message-input-btn {
    height: 38px;
    padding: 0 1rem;
}

