.message-item {
    position: relative;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.message-item:hover {
    background: #f8f9fa;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.message-author {
    font-size: 0.95rem;
    color: #1a1a2e;
}

.message-time {
    font-size: 0.75rem;
    color: #8e9297;
}

.message-content {
    font-size: 0.9rem;
    color: #2e3338;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reaction-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    background: #f0f1f3;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background: #e3e5e8;
    border-color: #5865f2;
}

.reaction-count {
    font-size: 0.75rem;
    color: #5865f2;
    font-weight: 600;
}

.thread-link {
    display: inline-block;
    margin-top: 0.25rem;
    padding: 2px 6px;
    font-size: 0.8rem;
    color: #5865f2;
    background: none;
    border: none;
    cursor: pointer;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
    padding: 2px;
}

.action-btn {
    padding: 2px 8px;
    font-size: 0.78rem;
    border: none;
    background: none;
    border-radius: 3px;
    cursor: pointer;
    color: #4f5660;
    white-space: nowrap;
}

.action-btn:hover {
    background: #e3e5e8;
    color: #1a1a2e;
}

.emoji-picker {
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
    padding: 6px;
    margin-top: 4px;
    width: fit-content;
}

.emoji-btn {
    font-size: 1.25rem;
    width: 34px;
    height: 34px;
    border: none;
    background: none;
    border-radius: 4px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
}

.emoji-btn:hover {
    background: #e3e5e8;
}

