@namespace sv_fc51ea4e49eb4bf68592feff62d3fa39.Components.Chat
@using sv_fc51ea4e49eb4bf68592feff62d3fa39.Services
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="message-area-header">
        <h5 class="mb-0"># @ChannelName</h5>
        <span class="text-muted header-desc">@ChannelDescription</span>
    </div>

    <div class="message-list" @ref="messageListRef">
        @if (IsLoadingMore)
        {
            <div class="load-more-indicator">
                <span class="spinner-border spinner-border-sm me-2"></span> Loading older messages...
            </div>
        }
        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ReplyCount="GetReplyCount(msg.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput OnSubmit="HandleSend" />
</div>

@code {
    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSend { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference messageListRef;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<MessageArea>? dotNetRef;
    private bool shouldScrollToBottom = true;
    private string? lastChannelName;

    protected override void OnParametersSet()
    {
        if (lastChannelName != ChannelName)
        {
            shouldScrollToBottom = true;
            lastChannelName = ChannelName;
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./js/chat-scroll.js");
            dotNetRef = DotNetObjectReference.Create(this);
            await jsModule.InvokeVoidAsync("observeScrollTop", messageListRef, dotNetRef);
        }

        if (shouldScrollToBottom && jsModule is not null)
        {
            shouldScrollToBottom = false;
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (!IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    private async Task HandleSend(string content)
    {
        await OnSend.InvokeAsync(content);
        shouldScrollToBottom = true;
    }

    private int GetReplyCount(int messageId)
        => ThreadReplyCounts.GetValueOrDefault(messageId);

    public async ValueTask DisposeAsync()
    {
        dotNetRef?.Dispose();
        if (jsModule is not null)
        {
            await jsModule.DisposeAsync();
        }
    }
}

