@namespace sv_fc51ea4e49eb4bf68592feff62d3fa39.Components.Chat
@using sv_fc51ea4e49eb4bf68592feff62d3fa39.Services

<div class="thread-panel">
    <div class="thread-header">
        <h6 class="mb-0">Thread</h6>
        <button class="btn-close btn-close-sm" @onclick="OnClose" aria-label="Close thread"></button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <MessageItem Message="RootMessage" />
        </div>
        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>
    }

    <div class="thread-messages">
        @foreach (var reply in Replies)
        {
            <MessageItem Message="reply" />
        }
    </div>

    <MessageInput Placeholder="Reply in thread..." ButtonLabel="Reply" OnSubmit="OnReply" />
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }
}

.thread-panel {
    width: 350px;
    min-width: 280px;
    border-left: 1px solid #dee2e6;
    display: flex;
    flex-direction: column;
    background: #fff;
    flex-shrink: 0;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
    flex-shrink: 0;
}

.thread-header h6 {
    font-weight: 700;
}

.btn-close-sm {
    font-size: 0.65rem;
}

.thread-root {
    padding: 0.5rem 0;
    background: #f8f9fa;
    border-bottom: 1px solid #eee;
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 0.35rem 1rem;
    font-size: 0.75rem;
    color: #8e9297;
    border-bottom: 1px solid #eee;
}

.thread-divider::before,
.thread-divider::after {
    content: "";
    flex: 1;
    height: 1px;
    background: #dee2e6;
}

.thread-divider::before {
    margin-right: 0.5rem;
}

.thread-divider::after {
    margin-left: 0.5rem;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 0.25rem 0;
}

