@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <ChannelSidebar Channels="channels"
                    SelectedChannelId="selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@(selectedChannel?.Name ?? "")"
                 ChannelDescription="@(selectedChannel?.Description ?? "")"
                 Messages="topLevelMessages"
                 ThreadReplyCounts="threadReplyCounts"
                 IsLoadingMore="isLoadingMore"
                 OnLoadMore="LoadMoreMessages"
                 OnSend="SendMessage"
                 OnOpenThread="OpenThread"
                 OnReact="AddReaction" />

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> allMessages = [];
    private List<Message> topLevelMessages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 50;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messageSkip = 0;
        allMessages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        RefreshMessageViews();
        CloseThreadSync();
        await ChatService.MarkChannelReadAsync(channel.Id);
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;
        isLoadingMore = true;
        StateHasChanged();

        messageSkip += PageSize;
        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messageSkip, PageSize);
        allMessages.InsertRange(0, older);
        RefreshMessageViews();
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        allMessages.Add(msg);
        topLevelMessages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessage = allMessages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        isThreadOpen = true;
    }

    private void CloseThreadSync()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private void CloseThread() => CloseThreadSync();

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        threadReplyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task AddReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        if (selectedChannel is not null)
        {
            allMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messageSkip + PageSize);
            RefreshMessageViews();
        }
    }

    private void RefreshMessageViews()
    {
        topLevelMessages = allMessages.Where(m => m.ReplyToId is null).ToList();
        threadReplyCounts = allMessages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}
